var propostaIndexJs={propostaId:null,init:function(){$("#btnConfirmarCancelamento").off("click").on("click",function(){gl.Post("Cancelar","Propostas",{id:propostaIndexJs.propostaId},!0,function(){$("#modalConfirmacao").modal("hide");window.location.reload()})});$("#btnLimparFiltros").off("click").on("click",function(){$("#PontoAtendimentoId").val("");$("#SeguradoraId").val("");$("#NomeProdutor").val("");$("#CPF").val("");$("#Status").val("");$("form").submit()});$("#CPF").mask("000.000.000-00",{reverse:!0});$(".btStatus").off("click").on("click",function(){var n=$(this).data("proposta");propostaStatusJs.openStatus(n)});$(".btRegistrarOcorrencia").off("click").on("click",function(){var n=$(this).data("proposta");propostaIndexJs.abrirModalOcorrencia(n)})},confirmarCancelamento:function(n){propostaIndexJs.propostaId=n;$("#modalConfirmacao").modal("show")},navegarPara:function(n){$("#Pagina").val(n);$("#formNavigator").submit()},abrirModalOcorrencia:function(n){gl.RenderGet("PropostasOcorrenciasRegistrar","Propostas",{propostaId:n},"#modalOcorrencia",!0,null,function(){propostaJS.closeModalOcorrencia();$("#modalOcorrencia").fadeIn(300)})}};$(document).ready(function(){propostaIndexJs.init()});